st.markdown('<div class="hero"><div class="cross"></div><h1>VerseMatch</h1><p>Write what you feel or what you experienced.</p></div>', unsafe_allow_html=True)

text = st.text_area("Your thoughts", placeholder="Write what happened or how you feel...", height=180, label_visibility="collapsed")

if st.button("✦ Find my Bible verse", use_container_width=True, type="primary"):
    if text.strip():
        result, themes = get_match(text)
        st.session_state.result = result
        st.session_state.themes = themes
    else:
        st.warning("Write something first.")

if "result" in st.session_state:
    ref, quote = st.session_state.result
    themes = st.session_state.get("themes", [])
    safe_quote = html.escape(quote)
    safe_ref = html.escape(ref)
    theme_text = html.escape(", ".join(themes) if themes else "general encouragement")
    st.markdown(
        f'<div class="verse-card" style="background:#171522 !important;">'
        f'<div class="verse-text" style="color:#ffffff !important;background:#171522 !important;">{safe_quote}</div>'
        f'<div class="verse-ref" style="color:#d9ceff !important;">— {safe_ref}</div>'
        f'<div class="match-note">✦ Matched around: {theme_text}</div>'
        f'</div>',
        unsafe_allow_html=True
    )
    if st.button("↻ Another verse", use_container_width=True):
        result, themes = get_match(text, ref)
        st.session_state.result = result
        st.session_state.themes = themes
        st.rerun()

st.caption(f"VerseMatch • {len(VERSES)} Bible verses")
